<?php
use App\Http\Controllers\{EbookAdminController,BookController,CatalogController,DashboardController,EbookCatalogController,EbookReaderController,HomeController,LoanController,MasterDataController,NotificationController,ReadingListController,ReportController,SettingsController,UserController};
use App\Http\Controllers\Auth\AuthController;
use App\Http\Controllers\Auth\PasswordResetLinkController;
use App\Http\Controllers\Auth\NewPasswordController;
use Illuminate\Support\Facades\Route;
Route::get('/',[HomeController::class,'index'])->name('home');
Route::get('/katalog',[CatalogController::class,'index'])->name('catalog.index');
Route::get('/e-book',[EbookCatalogController::class,'index'])->name('ebooks.index');
Route::get('/e-book/{book}/baca',[EbookCatalogController::class,'access'])->name('ebooks.access');
Route::get('/katalog/cari',[CatalogController::class,'search'])->name('catalog.search')->middleware('throttle:60,1');
Route::get('/katalog/{book}',[CatalogController::class,'show'])->name('catalog.show');
Route::middleware('guest')->group(function(){
 Route::get('/masuk',[AuthController::class,'showLogin'])->name('login');
 Route::post('/masuk',[AuthController::class,'login'])->middleware('throttle:6,1')->name('login.store');
 Route::get('/daftar',[AuthController::class,'showRegister'])->name('register');
 Route::post('/daftar',[AuthController::class,'register'])->middleware('throttle:4,1')->name('register.store');
 Route::get('/lupa-kata-sandi',[PasswordResetLinkController::class,'create'])->name('password.request');
 Route::post('/lupa-kata-sandi',[PasswordResetLinkController::class,'store'])->middleware('throttle:5,1')->name('password.email');
 Route::get('/reset-password/{token}',[NewPasswordController::class,'create'])->name('password.reset');
 Route::post('/reset-password',[NewPasswordController::class,'store'])->middleware('throttle:5,1')->name('password.update');
});
Route::post('/keluar',[AuthController::class,'logout'])->middleware('auth')->name('logout');
Route::middleware(['auth','active-account','role:admin,staff,member'])->group(function(){
 Route::get('/dashboard',[DashboardController::class,'index'])->name('dashboard');
 Route::get('/pinjaman-saya',[LoanController::class,'mine'])->middleware('role:member')->name('loans.mine');
 Route::post('/buku/{book}/pinjam',[LoanController::class,'requestBorrow'])->middleware('role:member')->name('loans.request');
 Route::post('/buku/{book}/daftar-bacaan',[ReadingListController::class,'toggle'])->middleware('role:member')->name('reading-list.toggle');
 Route::get('/daftar-bacaan',[ReadingListController::class,'index'])->middleware('role:member')->name('reading-list.index');
 Route::get('/baca/{book}',[EbookReaderController::class,'show'])->middleware('role:member')->name('reader.show');
 Route::get('/baca/{book}/file',[EbookReaderController::class,'file'])->middleware('role:member')->name('reader.file');
 Route::get('/baca/{book}/unduh',[EbookReaderController::class,'download'])->middleware('role:member')->name('reader.download');
 Route::post('/baca/{book}/progress',[EbookReaderController::class,'progress'])->middleware('role:member')->name('reader.progress');
 Route::get('/admin/ebook',[EbookAdminController::class,'index'])->middleware('role:admin,staff')->name('admin.ebooks.index');
 Route::get('/admin/ebook/tambah',[EbookAdminController::class,'create'])->middleware('role:admin,staff')->name('admin.ebooks.create');
 Route::post('/admin/ebook',[EbookAdminController::class,'store'])->middleware('role:admin,staff')->name('admin.ebooks.store');
 Route::get('/admin/ebook/{book}/edit',[EbookAdminController::class,'edit'])->middleware('role:admin,staff')->name('admin.ebooks.edit');
 Route::put('/admin/ebook/{book}',[EbookAdminController::class,'update'])->middleware('role:admin,staff')->name('admin.ebooks.update');
 Route::get('/admin/buku',[BookController::class,'index'])->middleware('role:admin,staff')->name('books.index');
 Route::get('/admin/buku/tambah',[BookController::class,'create'])->middleware('role:admin,staff')->name('books.create');
 Route::post('/admin/buku',[BookController::class,'store'])->middleware('role:admin,staff')->name('books.store');
 Route::get('/admin/buku/{book}/edit',[BookController::class,'edit'])->middleware('role:admin,staff')->name('books.edit');
 Route::put('/admin/buku/{book}',[BookController::class,'update'])->middleware('role:admin,staff')->name('books.update');
 Route::post('/admin/buku/{book}/eksemplar',[BookController::class,'addCopies'])->middleware('role:admin,staff')->name('books.copies.store');
 Route::delete('/admin/buku/{book}',[BookController::class,'destroy'])->middleware('role:admin,staff')->name('books.destroy');
 Route::get('/operasional/pinjaman',[LoanController::class,'staffIndex'])->middleware('role:admin,staff')->name('loans.staff');
 Route::post('/operasional/pinjaman/{loan}/setujui',[LoanController::class,'approve'])->middleware('role:admin,staff')->name('loans.approve');
 Route::post('/operasional/pinjaman/{loan}/tolak',[LoanController::class,'reject'])->middleware('role:admin,staff')->name('loans.reject');
 Route::post('/operasional/pinjaman/{loan}/kembali',[LoanController::class,'returnBook'])->middleware('role:admin,staff')->name('loans.return');
 Route::post('/operasional/pinjaman/{loan}/verifikasi-denda',[LoanController::class,'verifyFine'])->middleware('role:admin,staff')->name('loans.fine.verify');
 Route::post('/operasional/pinjaman/{loan}/perpanjangan',[LoanController::class,'requestRenewal'])->middleware('role:member')->name('loans.renew.request');
 Route::post('/operasional/pinjaman/{loan}/perpanjangan/review',[LoanController::class,'reviewRenewal'])->middleware('role:admin,staff')->name('loans.renew.review');
});
Route::middleware(['auth','active-account','role:admin'])->prefix('admin')->name('admin.')->group(function(){
 Route::get('/pengguna',[UserController::class,'index'])->name('users.index'); Route::post('/pengguna',[UserController::class,'store'])->name('users.store'); Route::patch('/pengguna/{user}',[UserController::class,'update'])->name('users.update');
 Route::get('/master/{type}',[MasterDataController::class,'index'])->name('master.index'); Route::post('/master/{type}',[MasterDataController::class,'store'])->name('master.store'); Route::delete('/master/{type}/{id}',[MasterDataController::class,'destroy'])->name('master.destroy');
 Route::get('/laporan',[ReportController::class,'index'])->name('reports.index');
 Route::post('/aturan',[SettingsController::class,'update'])->name('settings.update');
});
Route::middleware(['auth','active-account'])->post('/notifikasi/baca-semua',[NotificationController::class,'readAll'])->name('notifications.read-all');
